{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Seek a higher general warranty cap, or accept 20% only if the separate protections above are obtained."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Make the A$250,000 basket a tipping basket: once exceeded, the full loss is recoverable, not merely the excess."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek at least a 24-month general warranty period, rather than 18 months, for a SaaS business."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title/capacity: cap at 100% of the purchase price, with a substantially longer survival period"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve title, tax, IP, debt, leakage, fraud, covenants and specific indemnities out of general caps, baskets, time limits and exclusive-remedy terms."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete general disclosure of the data room, public registers and unspecified records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject general data-room/public-record disclosure and constructive knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make receipt of a written, effective and unconditional Bluefen consent a Buyer-benefit CP."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark repayment, termination and release of all security must occur at or immediately before Completion, funded through the completion funds flow."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include them expressly in the funds flow or deduct them from the price."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require Ironquay IP cure: cleared payment evidence and confirmatory assignment, plus a broad specific indemnity."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Include a specific pre-Completion incident indemnity for notification, investigation, regulatory, remediation and third-party costs."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "If commitments were entered into for the transaction period or are not ordinary course, treat them as leakage"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Limit any exclusive remedy provision to ordinary warranty claims only."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The DD-012 share register is useful evidence, but it is not a substitute for a title warranty and Completion protection."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "IP: at minimum, a separate and longer survival period and materially higher cap for ownership, chain-of-title and infringement claims"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

